type AgentOperation = { op: 'add_track'; track: Track } | { op: 'update_project'; path: 'title' | 'tempo' | 'key'; value: string | number } | { op: 'update_track'; track_id: string; path: 'name' | 'instrument' | 'color'; value: string }
type AgentMode = 'local' | 'agent' | 'fallback'
type AgentProtocol = 'responses' | 'chat-completions'
type ApiConfig = { baseUrl: string; apiKey: string; model: string; protocol: AgentProtocol; musicBaseUrl: string; musicApiKey: string; musicModel: string; sfxBaseUrl: string; sfxApiKey: string; sfxModel: string; musicMode: 'structured' | 'audio'; rememberKey: boolean }
type SoundPlan = { title: string; prompt: string; duration_seconds: number; texture: string; envelope: string; space: string; events: Array<{ time: number; event: string }> }
type GeneratedAudio = { filename: string; url: string; provider: string; model?: string; source: 'audio-model' }
type ThemeChoice = 'dark' | 'light' | 'system'
type FontChoice = 'sans' | 'serif' | 'mono'
type Preferences = { theme: ThemeChoice; font: FontChoice; fontSize: 'compact' | 'default' | 'large'; reducedMotion: boolean }


const pageFromLocation = (): Page => {
  const value = new URLSearchParams(location.search).get('view')
  return value === 'concept' || value === 'studio' || value === 'sound' || value === 'settings' ? value : 'explore'
}
const definitionStepFromLocation = () => new URLSearchParams(location.search).get('step') === 'sound' ? 'sound' as const : 'brief' as const
const soundLabFromLocation = () => new URLSearchParams(location.search).get('lab') === 'fine' ? 'fine' as const : 'abstract' as const

const chordPitches = (root: number) => [root, root + 4, root + 7]
const defaultApiConfig: ApiConfig = { baseUrl: 'https://api.openai.com/v1', apiKey: '', model: 'gpt-4.1-mini', protocol: 'responses', musicBaseUrl: 'https://api.replicate.com/v1', musicApiKey: '', musicModel: 'meta/musicgen', sfxBaseUrl: 'https://api.elevenlabs.io/v1', sfxApiKey: '', sfxModel: 'elevenlabs/sound-generation', musicMode: 'structured', rememberKey: false }
const loadApiConfig = (): ApiConfig => { try { const saved = JSON.parse(localStorage.getItem('sonic-matter-agent') ?? '{}') as Partial<ApiConfig>; const rememberKey = Boolean(saved.rememberKey); return { ...defaultApiConfig, ...saved, rememberKey, apiKey: rememberKey ? (saved.apiKey ?? '') : '', musicApiKey: rememberKey ? (saved.musicApiKey ?? '') : '', sfxApiKey: rememberKey ? (saved.sfxApiKey ?? '') : '' } } catch { return defaultApiConfig } }
const defaultPreferences: Preferences = { theme: 'dark', font: 'sans', fontSize: 'default', reducedMotion: false }
const loadPreferences = (): Preferences => { try { return { ...defaultPreferences, ...JSON.parse(localStorage.getItem('sonic-matter-preferences') ?? '{}') } } catch { return defaultPreferences } }
const loadAccount = () => localStorage.getItem('sonic-matter-account') ?? ''
const gestureScale = [48, 50, 52, 55, 57, 60, 62, 64, 67, 69, 72, 74, 76]
const notes: Note[] = [{ id: '1', pitch: 60, start: 0, duration: .45, velocity: 92 }, { id: '2', pitch: 64, start: .55, duration: .35, velocity: 76 }, { id: '3', pitch: 67, start: 1.02, duration: .55, velocity: 88 }, { id: '4', pitch: 71, start: 1.7, duration: .35, velocity: 72 }, { id: '5', pitch: 67, start: 2.2, duration: .7, velocity: 84 }]
const base: Project = { title: DEFAULT_PROJECT_TITLE, tempo: 92, key: 'C Major', duration: 10, masterGain: .9, tracks: [{ id: 'melody', name: '灵感旋律', kind: 'midi', instrument: 'Glass Keys', color: '#7dd3fc', gain: .8, pan: 0, muted: false, solo: false, start: 0, notes }] }
const hz = (p: number) => 440 * Math.pow(2, (p - 69) / 12)
function downloadBlob(blob: Blob, filename: string) { const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); URL.revokeObjectURL(url) }

export default function App() {
  const playbackRequest = useRef(0)
  const [page, setPage] = useState<Page>(pageFromLocation); const [history, setHistory] = useState(() => createHistory(loadLocalProject(base))); const project = currentProject(history); const [activeTrackId, setActiveTrackId] = useState(''); const midiTracks = project.tracks.filter(track => track.kind === 'midi'); const currentTrackId = midiTracks.some(track => track.id === activeTrackId) ? activeTrackId : (midiTracks[0]?.id ?? ''); const [recording, setRecording] = useState(false); const [playing, setPlaying] = useState(false); const [playhead, setPlayhead] = useState(0); const [conceptWord, setConceptWord] = useState('冰山'); const [choice, setChoice] = useState<ConceptId>('psychological'); const [concepts, setConcepts] = useState<Record<ConceptId, Concept> | null>(null); const conceptTask = useAsyncTask(); const conceptLoading = conceptTask.loading; const editTask = useAsyncTask(); const agentLoading = editTask.loading; const soundTask = useAsyncTask(); const soundLoading = soundTask.loading; const musicTask = useAsyncTask(); const musicLoading = musicTask.loading; const [soundText, setSoundText] = useState('远处冰层断裂，落入深海，带有空旷回声'); const [soundReady, setSoundReady] = useState(false); const [soundPlan, setSoundPlan] = useState<SoundPlan | null>(null); const [soundAudio, setSoundAudio] = useState<GeneratedAudio | null>(null); const [mixer, setMixer] = useState({ length: 2.4, density: 42, brightness: 64, space: 78, compact: 35 }); const [notice, setNotice] = useState(''); const [agentMode, setAgentMode] = useState<AgentMode>('local'); const [agentInstruction, setAgentInstruction] = useState(''); const [apiConfig, setApiConfig] = useState<ApiConfig>(() => loadApiConfig()); const [preferences, setPreferences] = useState<Preferences>(() => loadPreferences()); const [account, setAccount] = useState(loadAccount); const audio = useRef<AudioContext | null>(null); const canvas = useRef<HTMLCanvasElement>(null); const projectFile = useRef<HTMLInputElement>(null); const gesture = useRef({ active: false, x: 0, y: 0, at: 0, cell: '' }); const recordingStarted = useRef(0); const playbackStarted = useRef(0); const playbackOffset = useRef(0); const playbackFrame = useRef(0); const cursor = useRef({ x: 0, y: 0, active: false }); const particles = useRef<{ x: number; y: number; r: number; life: number; color: string }[]>([]); const currentNotes = useMemo(() => primaryMelodyTrack(project)?.notes ?? [], [project])
  const [homeBrainstormOpen, setHomeBrainstormOpen] = useState(false)
  const [gameDefinition, setGameDefinition] = useState<GameDefinition>(() => project.gameDefinition ?? emptyGameDefinition())
  const persistedProject = useMemo(() => projectWithGameDefinition(project, gameDefinition), [project, gameDefinition])
  const [definitionStep, setDefinitionStep] = useState<'brief' | 'sound'>(definitionStepFromLocation)
  const [soundLab, setSoundLab] = useState<'abstract' | 'fine'>(soundLabFromLocation)
  // 云端工程（Demo 级）：身份是本机随机串，分享靠 ?p=<id>。实现见 web/src/cloud/cloud.ts。
  const [cloudOwner] = useState(() => loadOwnerId()); const [cloudId, setCloudId] = useState(''); const [clouds, setClouds] = useState<CloudSummary[]>([]); const [cloudNotice, setCloudNotice] = useState(''); const [cloudBusy, setCloudBusy] = useState(false)
  const tasks = [editTask, conceptTask, soundTask, musicTask]; const activeTask = tasks.find(item => item.loading) ?? tasks.find(item => item.error || item.canceled) ?? editTask
  const play = (pitch: number, velocity = .8, duration = .28, brightness = .55) => { const ctx = audio.current ?? (audio.current = new AudioContext()); if (ctx.state === 'suspended') void ctx.resume(); const now = ctx.currentTime; const gain = ctx.createGain(); const filter = ctx.createBiquadFilter(); const pan = ctx.createStereoPanner(); const main = ctx.createOscillator(); const air = ctx.createOscillator(); main.type = brightness < .34 ? 'sine' : brightness < .72 ? 'triangle' : 'sawtooth'; air.type = 'sine'; main.frequency.value = hz(pitch); air.frequency.value = hz(pitch) * 2; air.detune.value = 5; filter.type = 'lowpass'; filter.frequency.value = 750 + brightness * 4600; filter.Q.value = 1.5 + brightness * 3; pan.pan.value = brightness * 1.2 - .6; gain.gain.setValueAtTime(.0001, now); gain.gain.exponentialRampToValueAtTime(.075 * velocity, now + .012 + (1 - brightness) * .035); gain.gain.exponentialRampToValueAtTime(.0001, now + duration); main.connect(filter); air.connect(filter); filter.connect(gain).connect(pan).connect(ctx.destination); main.start(now); air.start(now); main.stop(now + duration + .04); air.stop(now + duration + .04) }
  const playChord = (pitches: number[], velocity = .8, duration = .28, brightness = .55) => { pitches.forEach((pitch, index) => play(pitch, velocity * (index === 0 ? 1 : .62), duration, Math.min(1, brightness + index * .025))) }
  // 手势记录是高频写入：这里直接调 setHistory（而不是 applyProject），既能被 React Compiler 认成事件处理器，也能靠合并 key 把一次连续手势记成一步。
  const triggerGesture = (e: React.PointerEvent<HTMLCanvasElement>, force = false) => { const el = canvas.current; if (!el || (!gesture.current.active && !force)) return; const r = el.getBoundingClientRect(); const x = Math.max(0, Math.min(r.width, e.clientX - r.left)); const y = Math.max(0, Math.min(r.height, e.clientY - r.top)); const nx = x / r.width; const ny = y / r.height; const now = performance.now(); const row = Math.max(0, Math.min(gestureScale.length - 1, Math.floor((1 - ny) * gestureScale.length))); const column = Math.max(0, Math.min(5, Math.floor(nx * 6))); const cell = `${row}:${column}`; const elapsed = Math.max(16, now - gesture.current.at); const distance = Math.hypot(x - gesture.current.x, y - gesture.current.y); cursor.current = { x, y, active: true }; if (!force && (cell === gesture.current.cell || now - gesture.current.at < 58)) return; const velocity = Math.max(.35, Math.min(1, .38 + distance / elapsed * .55)); const duration = .22 + nx * .28; const pitch = gestureScale[row]; const chord = chordPitches(pitch); gesture.current = { active: true, x, y, at: now, cell }; playChord(chord, velocity, duration, nx); const color = nx > .66 ? '#fb9ab0' : nx > .33 ? '#b9a7ff' : '#7dd3fc'; for (let i = 0; i < 3; i++) particles.current.push({ x: x + (Math.random() - .5) * 16, y: y + (Math.random() - .5) * 16, r: 2 + Math.random() * 5, life: 1, color }); if (recording) { const start = Math.min(9.8, Math.max(0, (now - recordingStarted.current) / 1000)); const chordNotes: Note[] = chord.map((chordPitch, index) => ({ id: `${now}-${row}-${column}-${index}`, pitch: chordPitch, start, duration, velocity: Math.round(velocity * 127 * (index === 0 ? 1 : .72)) })); setHistory(current => { const previous = currentProject(current); const target = primaryMelodyTrack(previous); const next = target ? { ...previous, tracks: previous.tracks.map(t => t.id === target.id ? { ...t, notes: [...(t.notes ?? []), ...chordNotes].slice(-96) } : t) } : { ...previous, tracks: [...previous.tracks, melodyTrackTemplate(chordNotes.slice(-96))] }; return pushHistory(current, next, '记录手势音符', { key: 'gesture-notes' }) }) } }
  const gestureStart = (e: React.PointerEvent<HTMLCanvasElement>) => { const r = e.currentTarget.getBoundingClientRect(); e.currentTarget.setPointerCapture(e.pointerId); gesture.current = { active: true, x: e.clientX - r.left, y: e.clientY - r.top, at: performance.now() - 100, cell: '' }; triggerGesture(e, true) }
  const gestureEnd = (e: React.PointerEvent<HTMLCanvasElement>) => { if (e.currentTarget.hasPointerCapture(e.pointerId)) e.currentTarget.releasePointerCapture(e.pointerId); gesture.current.active = false; gesture.current.cell = ''; cursor.current.active = false }
  useEffect(() => { const c = canvas.current; if (!c) return; const ctx = c.getContext('2d'); if (!ctx) return; const resize = () => { const r = c.getBoundingClientRect(); const d = devicePixelRatio || 1; c.width = r.width * d; c.height = r.height * d; ctx.setTransform(d, 0, 0, d, 0, 0) }; resize(); addEventListener('resize', resize); let frame = 0; const draw = () => { const r = c.getBoundingClientRect(); ctx.clearRect(0, 0, r.width, r.height); const g = ctx.createRadialGradient(r.width / 2, r.height / 2, 0, r.width / 2, r.height / 2, r.width * .65); g.addColorStop(0, 'rgba(84,88,190,.2)'); g.addColorStop(1, 'rgba(5,6,19,0)'); ctx.fillStyle = g; ctx.fillRect(0, 0, r.width, r.height); ctx.strokeStyle = 'rgba(185,192,255,.08)'; ctx.lineWidth = 1; for (let i = 1; i < gestureScale.length; i++) { const y = i / gestureScale.length * r.height; ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(r.width, y); ctx.stroke() } for (let i = 1; i < 6; i++) { const x = i / 6 * r.width; ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, r.height); ctx.stroke() } particles.current = particles.current.map(p => ({ ...p, y: preferences.reducedMotion ? p.y : p.y - .45, life: p.life - .018, r: p.r * .992 })).filter(p => p.life > 0); particles.current.forEach(p => { ctx.globalAlpha = p.life; ctx.fillStyle = p.color; ctx.shadowBlur = 18; ctx.shadowColor = p.color; ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2); ctx.fill() }); if (cursor.current.active) { ctx.globalAlpha = .9; ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.arc(cursor.current.x, cursor.current.y, 12, 0, Math.PI * 2); ctx.stroke() } ctx.globalAlpha = 1; ctx.shadowBlur = 0; frame = requestAnimationFrame(draw) }; draw(); return () => { cancelAnimationFrame(frame); removeEventListener('resize', resize) } }, [preferences.reducedMotion])
  useEffect(() => { if (!notice) return; const timer = window.setTimeout(() => setNotice(''), 4500); return () => window.clearTimeout(timer) }, [notice])
  const stopPlayback = (reset = false) => { playbackRequest.current++; stopProjectAudio(); cancelAnimationFrame(playbackFrame.current); setPlaying(false); if (reset) setPlayhead(0) }
  const startPlayback = async (from = playhead) => { const request = ++playbackRequest.current; const duration = projectDuration(project); const offset = from >= duration ? 0 : Math.max(0, from); stopProjectAudio(); cancelAnimationFrame(playbackFrame.current); playbackOffset.current = offset; setPlayhead(offset); setPlaying(true); try { const started = await playProjectAudio(project, offset); if (request !== playbackRequest.current || !started) return; playbackStarted.current = performance.now(); const tick = () => { const next = playbackOffset.current + (performance.now() - playbackStarted.current) / 1000; if (next >= duration) { stopProjectAudio(); setPlayhead(0); setPlaying(false); setNotice('工程播放完成，可以继续调整混音。'); return } setPlayhead(next); playbackFrame.current = requestAnimationFrame(tick) }; playbackFrame.current = requestAnimationFrame(tick) } catch (error) { if (request !== playbackRequest.current) return; setPlaying(false); setNotice(error instanceof Error ? error.message : '工程播放失败。') } }
  const seekPlayback = (next: number) => { const position = Math.max(0, Math.min(projectDuration(project), next)); if (playing) void startPlayback(position); else setPlayhead(position) }
  useEffect(() => () => { stopProjectAudio(); cancelAnimationFrame(playbackFrame.current) }, [])
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (!(event.metaKey || event.ctrlKey) || event.altKey) return
      const key = event.key.toLowerCase()
      if (key !== 'z' && key !== 'y') return
      const target = event.target as HTMLElement | null
      if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable)) return
      event.preventDefault()
      stopPlayback()
      const forward = key === 'y' || event.shiftKey
      setHistory(current => (forward ? redo(current) : undo(current)))
    }
    addEventListener('keydown', onKeyDown)
    return () => removeEventListener('keydown', onKeyDown)
  }, [])
  useEffect(() => { localStorage.setItem('sonic-matter-project', JSON.stringify(persistedProject)) }, [persistedProject])
  const go = (next: Page) => { setPage(next); setNotice(next === 'explore' ? '移动光标，寻找你的下一颗音符。' : '工程状态会在页面之间持续保留。') }
  useEffect(() => { document.documentElement.dataset.theme = preferences.theme; document.documentElement.dataset.font = preferences.font; document.documentElement.dataset.fontSize = preferences.fontSize; document.documentElement.dataset.motion = preferences.reducedMotion ? 'reduced' : 'full'; localStorage.setItem('sonic-matter-preferences', JSON.stringify(preferences)) }, [preferences])
  const agentBody = (body: object) => ({ ...body, agent: { baseUrl: apiConfig.baseUrl || undefined, apiKey: apiConfig.apiKey || undefined, model: apiConfig.model || undefined, protocol: apiConfig.protocol } })
  const agentRequest = <T,>(path: string, body: object, signal: AbortSignal) => apiFetch<T>(path, agentBody(body), { signal })
  const applyConcept = (concept: Concept, word = conceptWord) => { applyProject(`应用概念「${concept.title}」`, p => ({ ...p, title: `${word} · ${concept.title}`, tempo: concept.musicMapping?.tempo ?? p.tempo, key: concept.musicMapping?.key ?? p.key, concept: { word, title: concept.title, story: concept.story }, tracks: p.tracks.some(t => t.id === 'cello') ? p.tracks : [...p.tracks, { id: 'cello', name: '水下大提琴', kind: 'midi', instrument: concept.musicMapping?.instruments?.[1] ?? 'Cello', color: '#a78bfa', notes: [{ id: 'c1', pitch: 48, start: 1.8, duration: 1.2, velocity: 70 }, { id: 'c2', pitch: 51, start: 3.8, duration: 1.4, velocity: 78 }, { id: 'c3', pitch: 46, start: 6.9, duration: 1.8, velocity: 84 }] } as Track] })) }
  const generateConcept = (prompt = conceptWord, definition = gameDefinition) => conceptTask.run(async signal => { const input = buildUnderstandingInput(definition, prompt); const data = await agentRequest<{ concept: string; source?: AgentMode; warning?: string; interpretations: Parameters<typeof mapAgentConcepts>[1] }>('/api/concept/interpret', input, signal); const next = mapAgentConcepts(data.concept, data.interpretations); setConcepts(next); setAgentMode(data.source === 'agent' ? 'agent' : 'fallback'); setNotice(data.warning ?? `已结合游戏资料生成“${data.concept}”的三种游戏理解。`) }, '游戏理解')
  const applySelectedConcept = () => { const selected = concepts?.[choice]; if (!selected) return setNotice('请先生成游戏理解，再选择一个视角应用到音乐工程。'); applyConcept(selected, gameDefinition.brief.title.trim() || conceptWord); setNotice(`已将“${selected.title}”应用到音乐工程，可以前往音乐工作室继续编辑。`) }
  const editProject = (instructionOverride?: string) => { const instruction = (instructionOverride ?? agentInstruction).trim(); if (!instruction) { setNotice('先告诉 Agent 你想如何修改工程。'); return } return editTask.run(async signal => { const data = await agentRequest<{ assistant_message: string; operations: AgentOperation[]; source?: AgentMode }>('/api/project/edit', { project: persistedProject, instruction }, signal); applyProject('Agent 修改工程', previous => data.operations.reduce(applyOperation, previous)); setAgentMode(data.source === 'agent' ? 'agent' : 'fallback'); setNotice(data.assistant_message); setAgentInstruction('') }, '工程编辑') }
  const requestSoundPlan = async (signal: AbortSignal) => { const data = await agentRequest<SoundPlan & { source?: AgentMode; warning?: string }>('/api/sfx/plan', { description: soundText, mixer }, signal); setSoundPlan(data); setSoundReady(true); setAgentMode(data.source === 'agent' ? 'agent' : 'fallback'); return data }
  const generateSound = () => soundTask.run(async signal => { const data = await requestSoundPlan(signal); setNotice(data.warning ?? '音效 Agent 已生成结构化声音计划，可以交给实际音频模型。') }, '音效计划')
  const generateRealSound = () => soundTask.run(async signal => { if (!soundPlan) await requestSoundPlan(signal); const result = await apiFetch<GeneratedAudio>('/api/sfx/generate', { description: soundText, mixer, sfx: { baseUrl: apiConfig.sfxBaseUrl || undefined, apiKey: apiConfig.sfxApiKey || undefined, model: apiConfig.sfxModel || undefined } }, { signal, timeoutMs: LONG_TIMEOUT_MS }); setSoundAudio(result); setSoundReady(true); setAgentMode('agent'); setNotice('真实音效已生成，可以试听或加入工程。') }, '真实音效生成')
  const previewSound = () => { playSoundPreview(soundText, mixer); setNotice('正在用浏览器本地合成试听；满意后再调用真实音效 API。') }
  const addSound = async () => { if (!soundPlan && !soundAudio) return setNotice('先点“生成声音计划”或“生成真实音效”，再加入工程。'); setSoundReady(true); try { const source = soundAudio?.url ?? encodeSoundClip(soundText, mixer); const duration = source.startsWith(LOCAL_SOUND_CLIP_PREFIX) ? clipDurationFor(source) : await audioSourceDuration(source) || clipDurationFor(source, projectDuration(project)); const clips = [createClip([], source, 0, duration)]; const track: Track = { id: 'sfx', name: soundPlan?.title ?? '语义音效', kind: 'audio', instrument: 'SFX', color: '#fb7185', clips, gain: .8, pan: 0, muted: false, solo: false, start: 0 }; applyProject('加入音效轨', p => ({ ...p, tracks: p.tracks.some(t => t.id === 'sfx') ? p.tracks.map(t => t.id === 'sfx' ? { ...track, start: t.start ?? 0, gain: t.gain ?? .8, pan: t.pan ?? 0, muted: Boolean(t.muted), solo: Boolean(t.solo) } : t) : [...p.tracks, track] })); setNotice(soundAudio ? `真实音效已加入当前工程（${duration.toFixed(1)}s），可以拖动片段位置、裁剪或调整淡入淡出。` : '本地音效已加入工程：由声音计划实时合成，播放与 WAV / MP3 导出都会包含它。') } catch (error) { setNotice(error instanceof Error ? error.message : '音效加入工程失败。') } }
  const generateMusic = () => musicTask.run(async signal => { const prompt = buildMusicPrompt({ title: project.title, key: project.key, tempo: project.tempo, concept: project.concept?.title ?? '抽象声音草图', definition: gameDefinition, notes: currentNotes }); if (apiConfig.musicMode === 'structured') { const result = await agentRequest<{ title: string; tempo: number; key: string; duration: number; tracks: Array<{ id: string; name: string; instrument: string; color: string; notes: Note[] }>; source?: AgentMode; warning?: string }>('/api/music/plan', { project: persistedProject, prompt }, signal); const generatedTracks = result.tracks.map(track => ({ ...track, kind: 'midi' as const, gain: .8, pan: 0, muted: false, solo: false, start: 0 })); applyProject('Agent 生成可编辑工程', previous => ({ ...previous, title: result.title, tempo: result.tempo, key: result.key, duration: result.duration, tracks: [...previous.tracks.filter(track => !track.id.startsWith('ai-structure-')), ...generatedTracks] })); setAgentMode(result.source === 'agent' ? 'agent' : 'fallback'); setNotice(result.warning ?? 'Agent 已生成可编辑的 MIDI / 和弦工程；现在可以继续修改并导出 MIDI。'); return } const result = await apiFetch<GeneratedAudio>('/api/music/generate', { prompt, duration_seconds: 10, music: { baseUrl: apiConfig.musicBaseUrl || undefined, apiKey: apiConfig.musicApiKey || undefined, model: apiConfig.musicModel || undefined } }, { signal, timeoutMs: LONG_TIMEOUT_MS }); const duration = await audioSourceDuration(result.url) || 10; applyProject('AI 音频加入工程', previous => ({ ...previous, tracks: [...previous.tracks.filter(track => track.id !== 'ai-music'), { id: 'ai-music', name: 'AI 生成音频', kind: 'audio', instrument: 'Audio Model', color: '#c4b5fd', clips: [createClip([], result.url, 0, duration)], gain: .8, pan: 0, muted: false, solo: false, start: 0 }] })); setAgentMode('agent'); setNotice('真实 AI 音频已加入工程；拖动片段可对齐 MIDI 骨架，也可以裁剪或分割后再导出。') }, '音乐生成')
  const exportMidi = async () => { try { downloadBlob(await apiFetchBlob('/api/export/midi', { project }), `${project.title}.mid`); setNotice('MIDI 已导出。') } catch (error) { setNotice(errorMessage(error, 'MIDI 导出失败。')) } }
  const exportWav = async () => { try { setNotice('正在离线渲染完整工程…'); const rendered = await renderProjectAudio(project); downloadBlob(audioBufferToWav(rendered), `${project.title}.wav`); setNotice('MIDI 与真实音频轨已混音并导出 WAV。') } catch (error) { setNotice(error instanceof Error ? error.message : 'WAV 导出失败。') } }
  const exportMp3 = async () => { try { setNotice('正在离线渲染完整工程…'); const rendered = await renderProjectAudio(project); downloadBlob(audioBufferToMp3(rendered), `${project.title}.mp3`); setNotice('MIDI 与真实音频轨已混音并导出 MP3。') } catch (error) { setNotice(error instanceof Error ? error.message : 'MP3 导出失败。') } }
  const saveProject = () => { downloadBlob(new Blob([JSON.stringify(persistedProject, null, 2)], { type: 'application/json' }), `${project.title}.sonic.json`); setNotice('工程文件已保存；浏览器内也会持续自动保存。') }
  const openProject = async (file: File) => { try { const next = normalizeProject(JSON.parse(await file.text())); stopPlayback(true); resetHistory(next, `打开工程「${next.title}」`); setGameDefinition(next.gameDefinition ?? emptyGameDefinition()); setNotice(`已打开工程“${next.title}”。`) } catch (error) { setNotice(error instanceof Error ? error.message : '工程文件读取失败。') } finally { if (projectFile.current) projectFile.current.value = '' } }
  // 所有工程修改都走这里：updater 返回同一引用表示没有变化，也就不会产生历史。
  const applyProject = (label: string, updater: (previous: Project) => Project, key = '') => setHistory(current => pushHistory(current, updater(currentProject(current)), label, { key }))
  const resetHistory = (next: Project, label: string) => setHistory(createHistory(next, label))
  /** 载入云端工程并接管为当前工程。第一个同步动作就是发请求，所以可以在 effect 里直接调用。 */
  const adoptCloudProject = async (id: string, shared = false) => { try { const data = await loadCloudProject(id); const next = normalizeProject(data.project); stopPlayback(true); resetHistory(next, `${shared ? '打开分享的' : '打开云端工程'}「${next.title}」`); setGameDefinition(next.gameDefinition ?? emptyGameDefinition()); setCloudId(data.id); setCloudNotice(`已打开云端工程“${next.title}”（${formatWhen(data.updatedAt)}更新，第 ${data.revision} 版）。`) } catch (error) { setCloudNotice(errorMessage(error, shared ? '这个分享链接打不开：它可能已被删除，或者链接不完整。' : '打开云端工程失败。')) } }
  const openCloud = (id: string) => { setCloudBusy(true); return adoptCloudProject(id).finally(() => setCloudBusy(false)) }
  const refreshClouds = async () => { setCloudBusy(true); try { const data = await listCloudProjects(cloudOwner); setClouds(data.projects); setCloudNotice(`这台浏览器在云端有 ${data.owned} 个工程（上限 ${data.perOwnerLimit} 个）。`) } catch (error) { setCloudNotice(errorMessage(error, '云端工程列表读取失败。')) } finally { setCloudBusy(false) } }
  const saveToCloud = async () => { setCloudBusy(true); try { const saved = await saveCloudProject(cloudOwner, persistedProject, cloudId); setCloudId(saved.id); setCloudNotice(`${saved.revision > 1 ? `已更新云端工程（第 ${saved.revision} 版）` : '已保存到云端'}，分享链接：${shareLink(saved.id, location.origin)}`); setClouds((await listCloudProjects(cloudOwner)).projects) } catch (error) { setCloudNotice(errorMessage(error, '保存到云端失败。')) } finally { setCloudBusy(false) } }
  const deleteCloud = async (id: string) => { if (!confirm('删除后这个分享链接会立刻失效，确定删除吗？')) return; setCloudBusy(true); try { await removeCloudProject(cloudOwner, id); setClouds(list => list.filter(item => item.id !== id)); if (id === cloudId) setCloudId(''); setCloudNotice('云端工程已删除。') } catch (error) { setCloudNotice(errorMessage(error, '删除云端工程失败。')) } finally { setCloudBusy(false) } }
  const copyCloudLink = async () => { if (!cloudId) return; const link = shareLink(cloudId, location.origin); setCloudNotice((await copyText(link)) ? `分享链接已复制：${link}` : `浏览器不允许自动复制，请手动复制：${link}`) }
  const cloud: CloudBarProps = { cloudId, busy: cloudBusy, notice: cloudNotice, projects: clouds, onSave: () => void saveToCloud(), onRefresh: () => void refreshClouds(), onOpen: id => void openCloud(id), onDelete: id => void deleteCloud(id), onCopyLink: () => void copyCloudLink() }
  // 别人发来的分享链接：打开时按 ?p=<id> 载入。前端没有路由，所以只认这一个查询参数。
  // 这里必须用 effect 发一次请求：URL 是外部输入，首屏渲染时才知道要载入哪个工程，没法在渲染期同步拿到。
  // oxlint-disable-next-line react/set-state-in-effect -- 载入分享工程是一次真正的网络同步，不是可派生的状态
  useEffect(() => { const shared = projectIdFromSearch(location.search); if (shared) void adoptCloudProject(shared, true) }, [])
  const undoProject = () => { stopPlayback(); setHistory(current => undo(current)) }
  const redoProject = () => { stopPlayback(); setHistory(current => redo(current)) }
  const updateTrack = (id: string, patch: Partial<Track>, label = '调整轨道') => { if (playing) stopPlayback(); applyProject(label, previous => ({ ...previous, tracks: previous.tracks.map(track => track.id === id ? { ...track, ...patch } : track) }), `track:${id}:${Object.keys(patch).sort().join(',')}`) }
  // 新建 / 复制之后直接切到那条轨道，用户可以马上在钢琴卷帘里编辑它。
  const editClips = (id: string, edit: (clips: Clip[]) => Clip[], label: string) => { if (playing) stopPlayback(); applyProject(label, previous => { const track = previous.tracks.find(item => item.id === id); return track ? setTrackClips(previous, id, edit(clipsOf(track))) : previous }, `track:${id}:clips`) }
  const addTrack = (instrument: string, name: string) => { const created = createTrack(project, instrument, name); setActiveTrackId(created.id); applyProject(`新建轨道「${name.trim() || instrument}」`, previous => insertTrack(previous, created)) }
  const copyTrack = (id: string) => { const track = project.tracks.find(item => item.id === id); if (!track) return; const next = duplicateTrack(project, id); const copy = next.tracks.find(item => !project.tracks.some(source => source.id === item.id)); if (copy) setActiveTrackId(copy.id); applyProject(`复制轨道「${track.name}」`, () => next) }
  const removeTrackById = (id: string) => { const track = project.tracks.find(item => item.id === id); if (!track || !canRemoveTrack(project, id)) return; if (playing) stopPlayback(); applyProject(`删除轨道「${track.name}」`, previous => removeTrack(previous, id)) }
  const moveTrackById = (id: string, delta: number) => applyProject(delta < 0 ? '轨道上移' : '轨道下移', previous => moveTrack(previous, id, delta))
  const renameTrackById = (id: string, name: string) => applyProject('重命名轨道', previous => renameTrack(previous, id, name), `track-name:${id}`)
  const changeInstrument = (id: string, instrument: string) => { if (playing) stopPlayback(); applyProject('切换乐器', previous => setTrackInstrument(previous, id, instrument), `track-instrument:${id}`) }
  const updateMasterGain = (gain: number) => { if (playing) stopPlayback(); applyProject('调整主音量', previous => ({ ...previous, masterGain: gain }), 'master-gain') }

  const saveApiConfig = (next: ApiConfig) => { setApiConfig(next); localStorage.setItem('sonic-matter-agent', JSON.stringify({ ...next, apiKey: next.rememberKey ? next.apiKey : '', musicApiKey: next.rememberKey ? next.musicApiKey : '', sfxApiKey: next.rememberKey ? next.sfxApiKey : '', rememberKey: next.rememberKey })); setNotice('Agent、音乐和音效服务配置已保存在当前浏览器。') }
  return <div className={'app app-page-' + page + ' definition-step-' + definitionStep}>
    <header className="app-header"><button className="brand" onClick={() => go('explore')} aria-label="返回首页"><span className="brand-mark">S</span><strong>SONIC / MATTER</strong></button><nav className="workflow-nav" aria-label="创作流程"><Nav active={page === 'explore'} label="开始" onClick={() => go('explore')} /><Nav active={page === 'concept' && definitionStep === 'brief'} label="游戏简报" onClick={() => { setDefinitionStep('brief'); go('concept') }} /><Nav active={page === 'concept' && definitionStep === 'sound'} label="声音方向" onClick={() => { setDefinitionStep('sound'); go('concept') }} /><Nav active={page === 'studio'} label="音乐工作室" onClick={() => go('studio')} /><Nav active={page === 'sound'} label="音效实验室" onClick={() => go('sound')} /></nav><div className="header-actions"><span className={'online ' + agentMode}><b>●</b>{agentMode === 'agent' ? 'Agent 已连接' : agentMode === 'fallback' ? '本地回退模式' : '本地工程已同步'}</span><button className={'settings-button' + (page === myPage ? ' active' : '')} aria-current={page === myPage ? 'page' : undefined} aria-label="项目与设置" onClick={() => go(myPage)}>⚙</button></div></header>
    <main className="app-main">
      {page === 'explore' && <Explore project={project} canvas={canvas} recording={recording} move={triggerGesture} start={gestureStart} end={gestureEnd} setRecording={() => { setRecording(v => { if (!v) recordingStarted.current = performance.now(); return !v }); setNotice(recording ? '已停止录制，旋律已保存。' : '录制已开始，按住并拖动来演奏。') }} play={() => playing ? stopPlayback() : void startPlayback(0)} playing={playing} noteCount={currentNotes.length} goDefine={() => go('concept')} onBrainstorm={prompt => { const nextDefinition = seedDefinitionFromIdea(gameDefinition, prompt); setGameDefinition(nextDefinition); setConceptWord(prompt); setHomeBrainstormOpen(false); go('concept'); void generateConcept(prompt, nextDefinition); setNotice('灵感已带入游戏资料草稿，并整理出一份概念理解。你可以继续补全游戏信息。') }} brainstormOpen={homeBrainstormOpen} setBrainstormOpen={setHomeBrainstormOpen} />}
      {page === 'concept' && <GameDefinitionPage definition={gameDefinition} setDefinition={setGameDefinition} setConceptWord={setConceptWord} step={definitionStep} setStep={setDefinitionStep} goStudio={() => go('studio')} goSound={() => go('sound')} />}
      {page === 'studio' && <Studio history={history} undoHistory={undoProject} redoHistory={redoProject} musicMode={apiConfig.musicMode} quickAddTrack={() => void editProject('添加一条与当前概念协调的新 MIDI 轨道')} project={project} playing={playing} play={() => void startPlayback()} stop={() => stopPlayback()} playhead={playhead} seek={seekPlayback} updateTrack={updateTrack} editClips={editClips} updateMasterGain={updateMasterGain} activeTrackId={currentTrackId} selectTrack={setActiveTrackId} addTrack={addTrack} copyTrack={copyTrack} removeTrack={removeTrackById} shiftTrack={moveTrackById} renameTrack={renameTrackById} changeInstrument={changeInstrument} saveProject={saveProject} openProject={() => projectFile.current?.click()} instruction={agentInstruction} setInstruction={setAgentInstruction} submit={() => void editProject()} loading={agentLoading} exportMidi={exportMidi} exportWav={exportWav} exportMp3={exportMp3} generateMusic={generateMusic} musicLoading={musicLoading} cloud={cloud} />}
      {page === 'sound' && <Sound definition={gameDefinition} conceptWord={conceptWord} setConceptWord={setConceptWord} concepts={concepts} choice={choice} setChoice={setChoice} generateConcept={generateConcept} conceptLoading={conceptLoading} applyConcept={applySelectedConcept} lab={soundLab} setLab={setSoundLab} preview={previewSound} text={soundText} setText={setSoundText} ready={soundReady} plan={soundPlan} audio={soundAudio} mixer={mixer} setMixer={setMixer} generate={generateSound} generateReal={generateRealSound} soundLoading={soundLoading} add={addSound} />}
      {page === 'settings' && <Settings value={apiConfig} preferences={preferences} account={account} onPreferences={setPreferences} onAccount={setAccount} onSave={saveApiConfig} onNotice={setNotice} />}
    </main>
    {page !== 'explore' && <footer><div><small>CURRENT PROJECT</small><strong>{project.title}</strong><span>{project.concept?.title ?? '探索中的声音草图'}</span></div><button onClick={() => playing ? stopPlayback() : void startPlayback()}>{playing ? 'Ⅱ' : '▶'}</button><div className="dockwave">▂▅▃▇▂▆▄▇▃▅▂▆</div><button className="outline" onClick={() => go('studio')}>打开工程 ↗</button></footer>}
    <input ref={projectFile} className="project-file" type="file" accept="application/json,.json" onChange={event => { const file = event.target.files?.[0]; if (file) void openProject(file) }} />
    <div className="toast-stack">{activeTask.loading ? <div className="toast pending" role="status" aria-live="polite"><strong>{activeTask.label}中…</strong><span>{activeTask.elapsed}s</span><button className="outline" onClick={activeTask.cancel}>取消</button></div> : null}{activeTask.error ? <div className="toast error" role="alert"><strong>出错了</strong><span>{activeTask.error}</span>{activeTask.retryable ? <button className="outline" onClick={activeTask.retry}>重试</button> : null}<button className="outline" onClick={activeTask.dismiss}>知道了</button></div> : null}{activeTask.canceled ? <div className="toast" role="status"><span>已取消这次请求。</span><button className="outline" onClick={activeTask.dismiss}>知道了</button></div> : null}{notice ? <div className="toast">{notice}</div> : null}</div>
  </div>
}
function applyOperation(project: Project, operation: AgentOperation): Project { if (operation.op === 'add_track') return project.tracks.some(t => t.id === operation.track.id) ? project : { ...project, tracks: [...project.tracks, operation.track] }; if (operation.op === 'update_project') return { ...project, [operation.path]: operation.value }; return { ...project, tracks: project.tracks.map(track => track.id === operation.track_id ? { ...track, [operation.path]: operation.value } : track) } }
function Nav({ active, label, onClick }: { active: boolean; label: string; onClick: () => void }) { return <button className={active ? 'active' : ''} aria-current={active ? 'page' : undefined} onClick={onClick}>{label}</button> }
function Explore({ project, canvas, recording, move, start, end, setRecording, play, playing, noteCount, goDefine, onBrainstorm, brainstormOpen, setBrainstormOpen }: { project: Project; canvas: React.RefObject<HTMLCanvasElement | null>; recording: boolean; move: (e: React.PointerEvent<HTMLCanvasElement>) => void; start: (e: React.PointerEvent<HTMLCanvasElement>) => void; end: (e: React.PointerEvent<HTMLCanvasElement>) => void; setRecording: () => void; play: () => void; playing: boolean; noteCount: number; goDefine: () => void; onBrainstorm: (prompt: string) => void; brainstormOpen: boolean; setBrainstormOpen: (open: boolean) => void }) {
  const [prompt, setPrompt] = useState('')
  return <section className="explore home-explore"><div className="home-main"><div className="home-copy"><small>AI GAME AUDIO WORKSPACE · 01</small><h1>让游戏先拥有<br /><em>声音的形状。</em></h1><p>从玩法、世界观与情绪开始，让 Agent 把抽象概念变成可编辑的音乐工程、轨道和音效，而不是一次性的音频文件。</p><div className="redesign-home-primary-actions"><button className="primary redesign-home-primary" onClick={goDefine}>{homeActions.define} <span>→</span></button><button className="secondary redesign-home-primary" onClick={() => setBrainstormOpen(!brainstormOpen)}>与 Agent 迸发灵感 <span>✦</span></button></div><div className="home-metrics"><div><strong>05</strong><span>创作阶段</span></div><div><strong>{project.tracks.length.toString().padStart(2, '0')}</strong><span>可编辑轨道</span></div><div><strong>WAV · MP3 · MIDI</strong><span>本地导出</span></div></div></div><div className="orb"><span className="axis top">HIGH · E5</span><span className="axis bottom">LOW · C3</span><span className="axis left">SOFT</span><span className="axis right">BRIGHT</span><canvas ref={canvas} onPointerDown={start} onPointerMove={move} onPointerUp={end} onPointerCancel={end} /><div className="pitch-ruler" aria-hidden="true">{gestureScale.map((pitch, index) => <span key={pitch} className={pitch % 12 === 0 ? 'root-note' : ''} style={{ top: (100 - (index + .5) / gestureScale.length * 100) + '%' }}><i />{pitchName(pitch)}<small>{pitch}</small></span>)}</div><div className="center"><strong>触碰声场</strong><span>拖动以产生 · 松开以记录</span></div><div className="live-input"><small>LIVE INPUT</small><strong>{project.key} · {project.tempo} BPM</strong><i>▂▅▃▆▂</i></div><div className="agent-listening"><small>AGENT LISTENING</small><strong>情绪正在形成：克制、悬浮、未知</strong></div></div></div><div className="home-project-strip"><div className="recent-project"><small>最近工程</small><div className="project-thumb" /><div><strong>{project.title}</strong><span>{project.tracks.length} 条轨道 · {noteCount} 个音符片段 · {project.tempo} BPM · {project.key}</span></div><span className="editable-state">可继续编辑</span><button className="secondary" onClick={goDefine}>继续创作</button></div><div className="creation-progress"><small>创作进度 <b>1 / 5</b></small><div className="progress-segments"><i className="active" /><i /><i /><i /><i /></div><strong>从一段游戏想法开始</strong><span>下一步：补充核心玩法、世界观和玩家情绪。</span></div></div><div className="home-transport"><button className="mini-control" aria-label={recording ? '停止录制' : '开始录制'} onClick={setRecording}>{recording ? '■' : '●'}</button><button className="mini-control" aria-label={playing ? '停止播放' : '播放旋律'} onClick={play}>{playing ? 'Ⅱ' : '▶'}</button><span>{noteCount} 个音符</span></div>{brainstormOpen && <div className="brainstorm-panel"><div><small>IDEA CONVERSATION</small><strong>把一个模糊念头交给 Agent</strong><p>对话结果会带入“游戏简报”，你可以继续修改后再生成声音方向。</p></div><div className="brainstorm-input"><input autoFocus value={prompt} onChange={event => setPrompt(event.target.value)} onKeyDown={event => { if (event.key === 'Enter' && prompt.trim()) onBrainstorm(prompt.trim()) }} placeholder="例如：一款关于潮汐与记忆的探索游戏" /><button className="primary" disabled={!prompt.trim()} onClick={() => onBrainstorm(prompt.trim())}>开始对话 ↵</button></div></div>}</section>
}
function GameDefinitionPage({ definition, setDefinition, setConceptWord, step, setStep, goStudio, goSound }: { definition: GameDefinition; setDefinition: React.Dispatch<React.SetStateAction<GameDefinition>>; setConceptWord: (value: string) => void; step: 'brief' | 'sound'; setStep: (step: 'brief' | 'sound') => void; goStudio: () => void; goSound: () => void }) {
  const [error, setError] = useState('')
  const updateBrief = (key: keyof GameDefinition['brief'], value: string) => setDefinition(current => ({ ...current, brief: { ...current.brief, [key]: value.slice(0, GAME_DEFINITION_LIMITS[key]) } }))
  const updateSound = (key: keyof GameDefinition['sound'], value: string) => setDefinition(current => ({ ...current, sound: { ...current.sound, [key]: value.slice(0, GAME_DEFINITION_LIMITS[key]) } }))
  const completeFields = Object.values(definition.brief).filter(value => value.trim()).length
  const completion = Math.round(completeFields / 5 * 100)
  const continueToSound = () => {
    if (!gameBriefComplete(definition.brief)) { setError('请先完整填写游戏名称、类型、核心玩法、世界设定和玩家体验。'); return }
    setError(''); setConceptWord(definition.brief.title.trim()); setStep('sound')
  }
  return <section className={'page definition-page ' + (step === 'brief' ? 'brief-stage' : 'direction-stage')}><div className="page-intro"><div><small>{step === 'brief' ? 'GAME DEFINITION · 01 / 05' : 'SOUND DIRECTION · 02 / 05'}</small><h1>{step === 'brief' ? <>定义这款游戏的<em>声音起点。</em></> : <>把情绪变成<em>可听见的参数。</em></>}</h1><p>{step === 'brief' ? '把玩法、世界与体验讲清楚。Agent 会把这份简报作为音乐与音效共同的创作背景。' : '选择核心情绪、推进方式和声音质感，建立音乐与音效都能遵循的声音指纹。'}</p></div><div className="page-score"><span style={{ '--score': (step === 'brief' ? completion : 86) + '%' } as React.CSSProperties}><b>{step === 'brief' ? completion : 86}%</b></span><div><strong>{step === 'brief' ? '简报完整度' : '方向清晰度'}</strong><small>{step === 'brief' && completion < 100 ? '继续补充关键信息' : '适合进入创作阶段'}</small></div></div></div>{step === 'brief' ? <div className="brief-workspace"><aside className="definition-steps" role="tablist"><button className={definition.brief.title && definition.brief.genre ? 'done' : 'active'} onClick={() => setStep('brief')}><small>{definition.brief.title && definition.brief.genre ? '✓' : '01'}</small><strong>项目身份</strong><span>名称与类型</span></button><button className={definition.brief.coreLoop ? 'done' : 'active'}><small>02</small><strong>核心循环</strong><span>玩家反复做什么</span></button><button className={definition.brief.world ? 'done' : ''}><small>03</small><strong>世界设定</strong><span>时间、地点、规则</span></button><button className={definition.brief.playerExperience ? 'done' : ''}><small>04</small><strong>玩家体验</strong><span>情绪与节奏变化</span></button><button onClick={continueToSound}><small>05</small><strong>声音方向</strong><span>风格与质感</span></button></aside><article className="definition-form"><div className="paneltitle"><span>游戏资料 / Game Brief</span><span>LOCAL DRAFT · AUTO SAVE</span></div><label><span>游戏名称</span><input value={definition.brief.title} onChange={event => updateBrief('title', event.target.value)} placeholder="例如：潮汐档案" /><small>PROJECT TITLE</small></label><label><span>游戏类型</span><input value={definition.brief.genre} onChange={event => updateBrief('genre', event.target.value)} placeholder="叙事探索 / Roguelike / 解谜" /><small>GENRE / FORM</small></label><label className="wide-field"><span>核心玩法</span><textarea value={definition.brief.coreLoop} onChange={event => updateBrief('coreLoop', event.target.value)} placeholder="玩家反复做什么？" rows={3} /><small>CORE LOOP · 玩家反复做什么？</small></label><label><span>世界设定</span><textarea value={definition.brief.world} onChange={event => updateBrief('world', event.target.value)} placeholder="时间、地点、规则和视觉氛围" rows={4} /><small>WORLD / RULES</small></label><label><span>希望玩家获得的体验</span><textarea value={definition.brief.playerExperience} onChange={event => updateBrief('playerExperience', event.target.value)} placeholder="紧张、好奇、平静，或某种情绪变化" rows={4} /><small>PLAYER EXPERIENCE</small></label><div className="definition-submit"><span>所有内容仅保存在当前工程，可随时返回修改。</span>{error && <p role="alert">{error}</p>}<button className="primary" onClick={continueToSound}>继续设置声音方向 →</button></div></article><aside className="brief-summary"><div className="paneltitle"><span>实时游戏摘要</span><span>AGENT CONTEXT</span></div><div className="summary-visual"><i /><i /><i /></div><h2>{definition.brief.title || '等待游戏名称'}</h2><p>{definition.brief.genre ? '一款以“' + (definition.brief.coreLoop.slice(0, 12) || '核心玩法') + '”为核心的' + definition.brief.genre + '游戏。' : '补充游戏类型与核心玩法后，这里会形成实时摘要。'}</p><dl><div><dt>核心动作</dt><dd>{definition.brief.coreLoop.slice(0, 18) || '等待补充'}</dd></div><div><dt>世界范围</dt><dd>{definition.brief.world.slice(0, 18) || '等待补充'}</dd></div><div><dt>体验曲线</dt><dd>{definition.brief.playerExperience.slice(0, 18) || '等待补充'}</dd></div></dl><div className="agent-tip"><small>AGENT 提示</small><p>{completeFields < 5 ? '把空白项补齐，声音系统才能区分探索、安全与冲突状态。' : '简报已经可以支撑声音方向设计，你仍可继续细化失败条件和状态变化。'}</p></div></aside></div> : <div className="direction-workspace"><article className="direction-console"><div className="paneltitle"><span>声音方向控制台</span><span>{definition.brief.title || 'CURRENT PROJECT'}</span></div><div className="direction-grid"><label><span>核心情绪</span><select value={definition.sound.mood} onChange={event => updateSound('mood', event.target.value)}><option>克制而神秘</option><option>温暖而怀旧</option><option>紧张而压迫</option><option>明亮而冒险</option><option>荒凉而宏大</option></select><small>选择声音的情绪重心</small></label><label><span>节奏倾向</span><select value={definition.sound.pace} onChange={event => updateSound('pace', event.target.value)}><option>舒缓流动</option><option>稳定推进</option><option>断续且不可预测</option><option>快速而有冲击力</option></select><small>决定音乐和音效如何推进</small></label><label><span>声音质感</span><select value={definition.sound.texture} onChange={event => updateSound('texture', event.target.value)}><option>有机与电子交织</option><option>纯合成与数字颗粒</option><option>原声乐器与环境录音</option><option>低保真与复古硬件</option></select><small>控制共同的材质语言</small></label><label><span>需要避免</span><textarea value={definition.sound.avoid} onChange={event => updateSound('avoid', event.target.value)} placeholder="例如：过于英雄化、密度太高" rows={3} /><small>NEGATIVE DIRECTION</small></label></div><div className="direction-destinations"><span>该方向会自动传递给 Music Studio 与 SFX Lab。</span><button className="secondary" onClick={goSound}>进入音效实验室</button><button className="primary" onClick={goStudio}>保存并进入音乐工作室 →</button></div></article><aside className="fingerprint-card"><div className="paneltitle"><span>声音指纹</span><span>LIVE PROFILE</span></div><div className="fingerprint"><i className="ring r1" /><i className="ring r2" /><i className="ring r3" /><i className="shape" /><b>神秘</b><b>电子</b><b>有机</b></div><div className="fingerprint-summary"><strong>{definition.sound.mood || '等待情绪方向'} · {definition.sound.texture || '等待质感'}</strong><p>{definition.sound.pace || '节奏待定'}；音乐与音效将共享这一组声音约束。</p></div><div className="concept-variations"><small>AGENT VARIATIONS</small><button className="active"><b>A / 推荐</b><span>潮汐残响</span></button><button><b>B</b><span>失真档案</span></button><button><b>C</b><span>雾中航标</span></button></div></aside></div>}</section>
}
function Studio({ project, history, undoHistory, redoHistory, playing, play, stop, playhead, seek, updateTrack, editClips, updateMasterGain, activeTrackId, selectTrack, addTrack, copyTrack, removeTrack, shiftTrack, renameTrack, changeInstrument, saveProject, openProject, instruction, setInstruction, submit, quickAddTrack, loading, exportMidi, exportWav, exportMp3, generateMusic, musicLoading, musicMode, cloud }: { project: Project; history: HistoryState; undoHistory: () => void; redoHistory: () => void; playing: boolean; play: () => void; stop: () => void; playhead: number; seek: (value: number) => void; updateTrack: (id: string, patch: Partial<Track>) => void; editClips: (id: string, edit: (clips: Clip[]) => Clip[], label: string) => void; updateMasterGain: (value: number) => void; activeTrackId: string; selectTrack: (id: string) => void; addTrack: (instrument: string, name: string) => void; copyTrack: (id: string) => void; removeTrack: (id: string) => void; shiftTrack: (id: string, delta: number) => void; renameTrack: (id: string, name: string) => void; changeInstrument: (id: string, instrument: string) => void; saveProject: () => void; openProject: () => void; instruction: string; setInstruction: (v: string) => void; submit: () => void; quickAddTrack: () => void; loading: boolean; exportMidi: () => void; exportWav: () => void; exportMp3: () => void; generateMusic: () => void; musicLoading: boolean; musicMode: ApiConfig['musicMode']; cloud: CloudBarProps }) {
  const duration = projectDuration(project)
  const time = (value: number) => `00:${Math.floor(value).toString().padStart(2, '0')}`
  return <section className="page studio-page"><div className="studio-commandbar"><div><small>CURRENT PROJECT</small><strong>{project.title}</strong><span>游戏声音 · 精编阶段 02</span></div><div className="transport"><button className="secondary" onClick={undoHistory}>↶</button><button className="transport-play" onClick={playing ? stop : play} aria-label={playing ? '停止播放' : '播放工程'}>{playing ? 'Ⅱ' : '▶'}</button><button className="secondary" onClick={redoHistory}>↷</button><strong className="transport-time">{time(playhead)}.{Math.floor(playhead % 1 * 10)} / {time(duration)}</strong><input aria-label="工程播放位置" type="range" min="0" max={duration} step="0.01" value={playhead} onChange={event => seek(Number(event.target.value))} /></div><div className="project-readout"><span><b>{project.tempo}</b>BPM</span><span><b>4 / 4</b>拍号</span><span><b>{project.key}</b>调式</span></div></div><div className="studio-workspace"><div className="studio-tracks"><TrackList project={project} activeTrackId={activeTrackId} quickAddTrack={quickAddTrack} loading={loading} onSelect={selectTrack} onPatch={updateTrack} onInstrument={changeInstrument} onAdd={addTrack} onDuplicate={copyTrack} onRemove={removeTrack} onMove={shiftTrack} onRename={renameTrack} /></div><div className="studio-timeline"><Timeline project={project} playhead={playhead} activeTrackId={activeTrackId} seek={seek} editClips={editClips} selectTrack={selectTrack} /></div><div className="studio-piano"><PianoRoll project={project} playhead={playhead} trackId={activeTrackId} onTrackChange={selectTrack} updateTrack={updateTrack} /></div><aside className="studio-agent"><div className="studio-agent-tabs"><button className="active">Agent</button><button>轨道</button><button>工程</button></div><div className="agent-card"><small>声音编排建议</small><p>根据当前游戏简报和声音方向，Agent 可以调整结构、密度、乐器与动态。</p><textarea value={instruction} onChange={event => setInstruction(event.target.value)} onKeyDown={event => { if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); submit() } }} placeholder="例如：降低低频密度，让第 2 段更紧张…" rows={4} /><div><button className="secondary" onClick={submit} disabled={loading}>{loading ? '执行中…' : '应用建议'}</button><button className="secondary" onClick={quickAddTrack} disabled={loading}>生成变体</button></div></div><label className="studio-slider"><span>主音量 <output>{Math.round((project.masterGain ?? .9) * 100)}%</output></span><input aria-label="主音量" type="range" min="0" max="1" step="0.01" value={project.masterGain ?? .9} onChange={event => updateMasterGain(Number(event.target.value))} /></label><div className="project-actions"><button className="secondary" onClick={openProject}>打开</button><button className="secondary" onClick={saveProject}>保存</button><button className="secondary" onClick={generateMusic} disabled={musicLoading}>{musicLoading ? '生成中…' : musicMode === 'structured' ? '生成工程' : 'AI 音频'}</button></div></aside></div><div className="studio-footer"><HistoryBar state={history} undo={undoHistory} redo={redoHistory} /><div className="master-meter"><b>MASTER −3.1 dB</b><i /><span>CPU 18%</span></div><div className="export-actions"><button className="secondary" onClick={exportMidi}>导出 MIDI</button><button className="secondary" onClick={exportWav}>导出 WAV</button><button className="primary" onClick={exportMp3}>导出音频</button></div></div><details className="cloud-drawer"><summary>云端工程与分享</summary><CloudBar {...cloud} /></details></section>
}
type SoundControlsProps = { preview: () => void; text: string; setText: (v: string) => void; ready: boolean; plan: SoundPlan | null; audio: GeneratedAudio | null; mixer: { length: number; density: number; brightness: number; space: number; compact: number }; setMixer: React.Dispatch<React.SetStateAction<{ length: number; density: number; brightness: number; space: number; compact: number }>>; generate: () => void; generateReal: () => void; soundLoading: boolean; add: () => void }
type SoundProps = SoundControlsProps & { definition: GameDefinition; conceptWord: string; setConceptWord: (value: string) => void; concepts: Record<ConceptId, Concept> | null; choice: ConceptId; setChoice: (value: ConceptId) => void; generateConcept: (prompt?: string, definition?: GameDefinition) => void; conceptLoading: boolean; applyConcept: () => void; lab: 'abstract' | 'fine'; setLab: (lab: 'abstract' | 'fine') => void }

function Sound({ definition, conceptWord, setConceptWord, concepts, choice, setChoice, generateConcept, conceptLoading, applyConcept, lab, setLab, ...controls }: SoundProps) {
  return <section className={'page sound-page sound-lab-' + lab}><div className="page-intro sound-intro"><div><small>SOUND DESIGN · 04 / 05</small><h1>把声音雕刻成<em>可用素材。</em></h1><p>从游戏语义生成结构化声音计划，再试听、微调并加入当前工程。</p></div><div className="sound-labs" role="group" aria-label="音效实验室工作区"><button className={lab === 'abstract' ? 'active' : ''} aria-pressed={lab === 'abstract'} onClick={() => setLab('abstract')}><span>01</span><strong>抽象实验室</strong><small>声音叙事</small></button><button className={lab === 'fine' ? 'active' : ''} aria-pressed={lab === 'fine'} onClick={() => setLab('fine')}><span>02</span><strong>微调实验室</strong><small>声音雕刻</small></button></div></div>{lab === 'abstract' ? <div className="abstract-shell"><AbstractLab definition={definition} focus={conceptWord} setFocus={setConceptWord} concepts={concepts} choice={choice} setChoice={setChoice} loading={conceptLoading} generate={() => generateConcept()} apply={applyConcept} /></div> : <SoundFineTune {...controls} />}</section>
}

function SoundFineTune({ preview, text, setText, ready, plan, audio, mixer, setMixer, generate, generateReal, soundLoading, add }: SoundControlsProps) {
  const waveformKey = [audio?.url ?? '', text.trim(), mixer.length, mixer.density, mixer.brightness, mixer.space, mixer.compact].join('|')
  const [waveform, setWaveform] = useState<{ key: string; peaks: number[] }>({ key: '', peaks: [] })
  useEffect(() => {
    const url = audio?.url; const description = text.trim(); if (!url && !description) return
    let alive = true
    const timer = setTimeout(() => { const request = url ? waveformPeaksFor(url, WAVEFORM_BUCKETS) : previewWaveform(description, mixer, WAVEFORM_BUCKETS); void request.then(peaks => { if (alive) setWaveform({ key: waveformKey, peaks }) }) }, url ? 0 : 260)
    return () => { alive = false; clearTimeout(timer) }
  }, [waveformKey, text, mixer, audio?.url])
  const peaks = waveform.key === waveformKey ? waveform.peaks : []
  const controls: [keyof typeof mixer, string, string, number, number][] = [['length', '长度', 's', .5, 6], ['density', '密度', '%', 0, 100], ['brightness', '明亮度', '%', 0, 100], ['space', '空间感', '%', 0, 100], ['compact', '紧凑度', '%', 0, 100]]
  return <div className="sfx-workspace"><aside className="sfx-library"><div className="paneltitle"><span>声音素材库</span><span>08 ITEMS</span></div>{['扫描器锁定','深井无线电','无人机掠过','舱门摩擦','错误确认','潮水拍岸'].map((item,index) => <button key={item} className={index === 0 ? 'active' : ''}><i /><strong>{item}</strong><span>{index % 2 ? 'AMBIENCE' : 'UI'} / {(1.8 + index * .6).toFixed(1)}s · V{Math.max(1,3-index)}</span></button>)}</aside><article className="sfx-stage"><div className="sfx-prompt"><textarea value={text} onChange={event => setText(event.target.value)} rows={2} aria-label="声音描述" /><button className="primary" onClick={generate}>生成声音计划 ✦</button></div><div className="wave-stage"><div className="waveform-display" data-peaks={peaks.length}>{Array.from({ length: WAVEFORM_BUCKETS }, (_, i) => <i key={i} style={{ height: (8 + Math.max(peaks[i] ?? 0, !ready && !audio ? Math.abs(Math.sin(i * .47)) * (1 - i / WAVEFORM_BUCKETS * .55) * .72 : 0) * 120) + 'px' }} />)}</div><span className="wave-marker" /><div className="wave-time"><span>0.0s</span><span>{(mixer.length / 3).toFixed(1)}s</span><span>{(mixer.length * 2 / 3).toFixed(1)}s</span><span>{mixer.length.toFixed(1)}s</span></div>{audio && <audio controls src={audio.url} />}</div><div className="sfx-versions"><button>V1 · 更低沉<small>低频靠前</small></button><button>V2 · 更短促<small>攻击更快</small></button><button className="active">V3 · 当前选择<small>{ready ? '清晰 / 克制' : '等待计划'}</small></button><button onClick={generateReal} disabled={soundLoading}>＋ {soundLoading ? '生成中…' : '生成变体'}<small>保留参数</small></button></div></article><aside className="semantic-mixer"><div className="paneltitle"><span>语义混音器</span><span>LIVE PREVIEW</span></div><div className="mixer-summary"><strong>{plan?.title ?? '当前声音 · SOUND PLAN'}</strong><p>{plan ? plan.texture + '；' + plan.envelope + '；' + plan.space : '先生成结构化声音计划，再调整各项语义参数。'}</p></div>{controls.map(([key,label,unit,min,max]) => <label className="mixer-control" key={key}><span>{label}<output>{mixer[key]}{unit}</output></span><input type="range" min={min} max={max} step={key === 'length' ? .1 : 1} value={mixer[key]} onChange={event => setMixer(value => ({ ...value, [key]: Number(event.target.value) }))} /></label>)}<div className="mixer-actions"><button className="secondary" onClick={preview}>▶ 本地试听</button><button className="primary" onClick={add}>{ready ? '加入当前工程' : '先生成候选'}</button></div></aside></div>
}

function AgentSettings({ value, onSave, onNotice }: { value: ApiConfig; onSave: (value: ApiConfig) => void; onNotice: (value: string) => void }) {
  const [form, setForm] = useState(value)
  const [testing, setTesting] = useState(false)
  const update = <K extends keyof ApiConfig>(key: K, next: ApiConfig[K]) => setForm(current => ({ ...current, [key]: next }))
  const test = async () => {
    setTesting(true)
    try {
      const data = await apiFetch<{ message?: string }>('/api/agent/test', { agent: { baseUrl: form.baseUrl || undefined, apiKey: form.apiKey || undefined, model: form.model || undefined, protocol: form.protocol } }, { timeoutMs: 30_000 })
      onNotice(`连接成功：${data.message ?? 'Agent 已响应。'}`)
    } catch (error) { onNotice(errorMessage(error, '连接失败。')) } finally { setTesting(false) }
  }
  const validateService = (name: string, baseUrl: string, apiKey: string, model: string) => {
    if (!baseUrl.trim()) return onNotice(`${name} Base URL 不能为空。`)
    try { new URL(baseUrl) } catch { return onNotice(`${name} Base URL 不是有效的网址。`) }
    if (!apiKey.trim()) return onNotice(`请填写 ${name} API Key；如果只想使用本地结构化渲染，可以暂时留空。`)
    if (!model.trim()) return onNotice(`请填写 ${name} Model。`)
    onNotice(`${name} 配置格式检查通过；点击保存后，生成请求会使用这组配置。`)
  }
  return <div className="settings-grid service-settings-grid">
    <div className="settings-card">
      <div className="paneltitle"><span>AGENT SERVICE</span><span>JSON SCHEMA</span></div>
      <label className="setting-row"><span>Base URL</span><input value={form.baseUrl} onChange={e => update('baseUrl', e.target.value)} placeholder="https://api.openai.com/v1" /></label>
      <label className="setting-row"><span>API Key</span><input type="password" value={form.apiKey} onChange={e => update('apiKey', e.target.value)} placeholder="sk-..." /></label>
      <label className="setting-row"><span>Model</span><input value={form.model} onChange={e => update('model', e.target.value)} placeholder="模型名称" /></label>
      <label className="setting-row"><span>Protocol</span><select value={form.protocol} onChange={e => update('protocol', e.target.value as AgentProtocol)}><option value="responses">Responses API</option><option value="chat-completions">Chat Completions / JSON Schema</option></select></label>
      <label className="check-row"><input type="checkbox" checked={form.rememberKey} onChange={e => update('rememberKey', e.target.checked)} /><span>记住 API Key（仅当前浏览器 localStorage）</span></label>
      <div className="settings-actions"><button className="secondary" onClick={test} disabled={testing}>{testing ? '测试中…' : '测试 Agent'}</button><button className="primary" onClick={() => onSave(form)}>保存全部配置</button></div>
      <p className="security-note">Agent 负责概念解读、结构化音乐工程和轨道编辑。API Key 只会通过本机后端转发，不会写入项目文件。</p>
    </div>
    <div className="settings-card">
      <div className="paneltitle"><span>MUSIC SERVICE</span><span>OPTIONAL ENHANCEMENT</span></div>
      <label className="setting-row"><span>Base URL</span><input value={form.musicBaseUrl} onChange={e => update('musicBaseUrl', e.target.value)} placeholder="https://api.replicate.com/v1" /></label>
      <label className="setting-row"><span>API Key</span><input type="password" value={form.musicApiKey} onChange={e => update('musicApiKey', e.target.value)} placeholder="服务商 API Key" /></label>
      <label className="setting-row"><span>Model</span><input value={form.musicModel} onChange={e => update('musicModel', e.target.value)} placeholder="meta/musicgen" /></label>
      <label className="setting-row"><span>生成方式</span><select value={form.musicMode} onChange={e => update('musicMode', e.target.value as ApiConfig['musicMode'])}><option value="structured">结构化工程（推荐）</option><option value="audio">直接 AI 音频增强</option></select></label>
      <div className="settings-actions"><button className="secondary" onClick={() => validateService('音乐服务', form.musicBaseUrl, form.musicApiKey, form.musicModel)}>检查配置</button></div>
      <p className="security-note">推荐默认使用 Agent 生成可编辑的 MIDI / 和弦工程，再用本地 WebAudio 渲染。这里的音乐 API 只作为氛围和演奏层增强，不会替代 MIDI。</p>
    </div>
    <div className="settings-card">
      <div className="paneltitle"><span>SFX SERVICE</span><span>OPTIONAL</span></div>
      <label className="setting-row"><span>Base URL</span><input value={form.sfxBaseUrl} onChange={e => update('sfxBaseUrl', e.target.value)} placeholder="https://api.elevenlabs.io/v1" /></label>
      <label className="setting-row"><span>API Key</span><input type="password" value={form.sfxApiKey} onChange={e => update('sfxApiKey', e.target.value)} placeholder="服务商 API Key" /></label>
      <label className="setting-row"><span>Model</span><input value={form.sfxModel} onChange={e => update('sfxModel', e.target.value)} placeholder="elevenlabs/sound-generation" /></label>
      <div className="settings-actions"><button className="secondary" onClick={() => validateService('音效服务', form.sfxBaseUrl, form.sfxApiKey, form.sfxModel)}>检查配置</button></div>
      <p className="security-note">音效服务用于将 Agent 生成的声音计划变成真实音频。没有 Key 时仍可使用结构化计划和本地试听 fallback。</p>
    </div>
    <div className="settings-card explain">
      <div className="paneltitle"><span>PIPELINE</span><span>RECOMMENDED</span></div>
      <div className="provider"><strong>1 / Agent</strong><span>把概念、和弦、节奏和轨道写成可校验的 Project JSON。</span></div>
      <div className="provider"><strong>2 / Local Render</strong><span>使用本地音色和 WebAudio 渲染，保留 MIDI 可编辑性和导出能力。</span></div>
      <div className="provider"><strong>3 / API Enhance</strong><span>音乐 API 和音效 API 都是可选增强层；三组服务可以一次性填写并统一保存。</span></div>
    </div>
  </div>
}
function Settings({ value, preferences, account, onPreferences, onAccount, onSave, onNotice }: { value: ApiConfig; preferences: Preferences; account: string; onPreferences: (value: Preferences) => void; onAccount: (value: string) => void; onSave: (value: ApiConfig) => void; onNotice: (value: string) => void }) { const [tab, setTab] = useState<'account' | 'appearance' | 'agent'>('account'); const [email, setEmail] = useState(account); const [password, setPassword] = useState(''); const login = () => { if (!email.trim() || password.length < 4) return onNotice('请输入邮箱和至少 4 位密码。'); localStorage.setItem('sonic-matter-account', email.trim()); onAccount(email.trim()); setPassword(''); onNotice('已建立本地 Demo 会话；该邮箱仅作为当前浏览器标记，不会创建服务器账号。') }; const logout = () => { localStorage.removeItem('sonic-matter-account'); onAccount(''); onNotice('已退出本地会话。') }; return <section className="page settings-page"><div className="heading"><div><small>ACCOUNT / APPEARANCE / AGENT</small><h1>设置你的<em>创作环境。</em></h1><p>管理本地会话、界面显示和模型连接。</p></div><span>SETTINGS</span></div><div className="settings-tabs" role="tablist"><button className={tab === 'account' ? 'active' : ''} onClick={() => setTab('account')}>账户</button><button className={tab === 'appearance' ? 'active' : ''} onClick={() => setTab('appearance')}>外观</button><button className={tab === 'agent' ? 'active' : ''} onClick={() => setTab('agent')}>Agent</button></div>{tab === 'account' && <div className="settings-grid"><div className="settings-card"><div className="paneltitle"><span>ACCOUNT</span><span>{account ? 'LOCAL SESSION' : 'LOCAL DEMO'}</span></div>{account ? <div className="account-state"><span className="avatar">{account.slice(0, 1).toUpperCase()}</span><div><strong>{account}</strong><p>此标记仅存在当前浏览器，不会创建或验证服务器账号。</p></div><button className="secondary" onClick={logout}>退出</button></div> : <><label className="setting-row"><span>邮箱</span><input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="name@example.com" /></label><label className="setting-row"><span>密码</span><input type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="至少 4 位" /></label><div className="settings-actions"><button className="primary" onClick={login}>登录</button></div><p className="security-note">本地演示入口：邮箱和密码不会发送到服务器；此功能不是账号认证。</p></>}</div><div className="settings-card explain"><div className="paneltitle"><span>PROJECT STORAGE</span><span>BROWSER + SQLITE</span></div><div className="provider"><strong>本地工程</strong><span>工程自动保存在当前浏览器，可导出 JSON 备份。</span></div><div className="provider"><strong>云端工程</strong><span>在音乐工作室保存到 SQLite 并生成分享链接；链接持有者可以查看工程。</span></div></div></div>}{tab === 'appearance' && <div className="settings-card appearance-card"><div className="paneltitle"><span>APPEARANCE</span><span>LIVE PREVIEW</span></div><div className="preference-row"><div><strong>主题</strong><span>跟随系统或固定明暗模式</span></div><div className="segmented">{(['dark', 'light', 'system'] as ThemeChoice[]).map(item => <button key={item} className={preferences.theme === item ? 'active' : ''} onClick={() => onPreferences({ ...preferences, theme: item })}>{item === 'dark' ? '深色' : item === 'light' ? '浅色' : '跟随系统'}</button>)}</div></div><div className="preference-row"><div><strong>字体</strong><span>改变全站正文和控件字形</span></div><div className="segmented">{(['sans', 'serif', 'mono'] as FontChoice[]).map(item => <button key={item} className={preferences.font === item ? 'active' : ''} onClick={() => onPreferences({ ...preferences, font: item })}>{item === 'sans' ? '现代' : item === 'serif' ? '人文' : '等宽'}</button>)}</div></div><div className="preference-row"><div><strong>字号</strong><span>控制界面信息密度</span></div><div className="segmented">{(['compact', 'default', 'large'] as Preferences['fontSize'][]).map(item => <button key={item} className={preferences.fontSize === item ? 'active' : ''} onClick={() => onPreferences({ ...preferences, fontSize: item })}>{item === 'compact' ? '紧凑' : item === 'default' ? '标准' : '放大'}</button>)}</div></div><label className="preference-row switch-row"><div><strong>减少动态效果</strong><span>降低粒子漂移和界面过渡</span></div><input type="checkbox" checked={preferences.reducedMotion} onChange={e => onPreferences({ ...preferences, reducedMotion: e.target.checked })} /></label></div>}{tab === 'agent' && <AgentSettings value={value} onSave={onSave} onNotice={onNotice} />}</section> }
